/* Proyecto: Sistema Modular de Gestión OxiTigre | Componente: Smoke Fase 7 | Archivo: SMOKE_FASE7.sql | Versión: 1.1.0 | Fecha: 2026-08-26 | ID pedido: FABRICA
Desarrollador: Agustin Omar Cauzi | Correo: agustincauzi10@hotmail.com | Descripción funcional: Verifica compras parciales, reversión y trazabilidad sin persistir cambios. | Historial: 1.0.0 | 2026-08-24 | FABRICA | Agustin Omar Cauzi | Creación inicial. | Historial: 1.1.0 | 2026-08-26 | FABRICA | Agustin Omar Cauzi | Reversión compensatoria. */
SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRANSACTION;
DECLARE @EMP BIGINT=(SELECT ID_EMPRESA FROM CONFIGURACION.EMPRESAS WHERE CODIGO=N'OXITIGRE'),@USR BIGINT=(SELECT ID_USUARIO FROM SEGURIDAD.USUARIOS WHERE NOMBRE_USUARIO=N'AOCAUZI'),@DEP BIGINT=(SELECT ID_DEPOSITO FROM INVENTARIO.DEPOSITOS WHERE CODIGO=N'CENTRAL'),@PROV BIGINT=(SELECT ID_PROVEEDOR FROM COMPRAS.PROVEEDORES WHERE CUIT=N'30-70000001-6'),@PRODUCT BIGINT=(SELECT ID_PRODUCTO FROM INVENTARIO.PRODUCTOS WHERE CODIGO_BARRAS=N'DEV-CODO-001'),@CO2 BIGINT=(SELECT ID_PRODUCTO FROM INVENTARIO.PRODUCTOS WHERE CODIGO_BARRAS=N'DEV-CO2-GRANEL'),@LOT BIGINT=(SELECT ID_LOTE FROM INVENTARIO.LOTES WHERE CODIGO=N'LOT-CO2-2026-001'),@ASSET BIGINT=(SELECT ID_ACTIVO FROM INVENTARIO.ACTIVOS WHERE NUMERO_SERIE=N'CIL-000101');
DECLARE @ID BIGINT,@ERR BIGINT,@MSG NVARCHAR(4000),@ROWS INT,@RV BINARY(8),@NOW DATETIME2(3)=SYSUTCDATETIME(),@END DATETIME2(3),@RETURN DATETIME2(3),@NEXT DATE,@JSON NVARCHAR(MAX);
SET @END=DATEADD(MINUTE,1,@NOW);SET @RETURN=DATEADD(HOUR,1,@NOW);SET @NEXT=DATEADD(YEAR,1,CONVERT(DATE,@NOW));
SET @JSON=N'[{"ProductId":'+CONVERT(NVARCHAR(20),@PRODUCT)+N',"Quantity":5,"UnitCost":100,"DiscountRate":0,"TaxRate":0.21}]';
EXEC COMPRAS.SP_ORDEN_COMPRA_SAVE @EMP,NULL,@PROV,@DEP,@NOW,NULL,N'ARS',N'Smoke Fase 7',@JSON,NULL,1,@USR,@ID OUTPUT,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR IS NOT NULL THROW 50000,@MSG,1;
SELECT @RV=ROW_VERSION FROM COMPRAS.ORDENES_COMPRA WHERE ID_ORDEN_COMPRA=@ID;EXEC COMPRAS.SP_ORDEN_COMPRA_SUBMIT @EMP,@ID,@RV,1,@USR,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR IS NOT NULL THROW 50000,@MSG,1;
SELECT @RV=ROW_VERSION FROM COMPRAS.ORDENES_COMPRA WHERE ID_ORDEN_COMPRA=@ID;EXEC COMPRAS.SP_ORDEN_COMPRA_APPROVE @EMP,@ID,@RV,1,@USR,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR IS NOT NULL THROW 50000,@MSG,1;
DECLARE @LINE BIGINT=(SELECT ID_ORDEN_COMPRA_DETALLE FROM COMPRAS.ORDENES_COMPRA_DETALLES WHERE ID_ORDEN_COMPRA=@ID),@REC BIGINT;SELECT @RV=ROW_VERSION FROM COMPRAS.ORDENES_COMPRA WHERE ID_ORDEN_COMPRA=@ID;SET @JSON=N'[{"PurchaseOrderLineId":'+CONVERT(NVARCHAR(20),@LINE)+N',"AcceptedQuantity":3,"RejectedQuantity":1,"DamagedQuantity":0,"DifferenceReason":"Faltan 2","Lots":[],"SerialNumbers":[],"ContainerContents":[]}]';
EXEC COMPRAS.SP_RECEPCION_CREATE @EMP,@ID,@NOW,N'SMOKE-REM',N'Recepción parcial',@JSON,@RV,1,@USR,@REC OUTPUT,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR IS NOT NULL THROW 50000,@MSG,1;IF(SELECT CODIGO_ESTADO FROM COMPRAS.ORDENES_COMPRA WHERE ID_ORDEN_COMPRA=@ID)<>N'RECIBIDA_PARCIAL' THROW 50000,'No quedó parcial.',1;
SELECT @RV=ROW_VERSION FROM COMPRAS.RECEPCIONES_COMPRA WHERE ID_RECEPCION=@REC;EXEC COMPRAS.SP_RECEPCION_REVERSE @EMP,@REC,N'Corrección smoke',@RV,1,@USR,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR IS NOT NULL THROW 50000,@MSG,1;IF(SELECT CODIGO_ESTADO FROM COMPRAS.RECEPCIONES_COMPRA WHERE ID_RECEPCION=@REC)<>N'REVERSADA' THROW 50000,'No se reversó la recepción.',1;IF(SELECT CODIGO_ESTADO FROM COMPRAS.ORDENES_COMPRA WHERE ID_ORDEN_COMPRA=@ID)<>N'APROBADA' THROW 50000,'La orden no volvió a aprobada.',1;IF(SELECT CANTIDAD_RECIBIDA FROM COMPRAS.ORDENES_COMPRA_DETALLES WHERE ID_ORDEN_COMPRA_DETALLE=@LINE)<>0 THROW 50000,'No se restituyó el saldo de la orden.',1;
SET @ERR=NULL;SET @MSG=NULL;EXEC COMPRAS.SP_RECEPCION_REVERSE @EMP,@REC,N'Repetición smoke',@RV,1,@USR,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR<>50008 THROW 50000,'La reversión repetida no devolvió 50008.',1;
DECLARE @MEAS BIGINT;EXEC INVENTARIO.SP_MEDICION_ACTIVO_CREATE @EMP,@ASSET,@NOW,N'CONTENIDO',10,N'kg',N'PESAJE',N'MANUAL',0,NULL,N'Smoke',1,@USR,@MEAS OUTPUT,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR IS NOT NULL THROW 50000,@MSG,1;
SET @JSON=N'[{"AssetId":'+CONVERT(NVARCHAR(20),@ASSET)+N',"LotId":'+CONVERT(NVARCHAR(20),@LOT)+N',"Quantity":1}]';DECLARE @TRANS BIGINT;EXEC INVENTARIO.SP_TRANSFORMACION_CREATE @EMP,@LOT,NULL,@CO2,@NOW,1.1,.1,N'PESAJE',N'Merma técnica',N'Smoke',@JSON,1,@USR,@TRANS OUTPUT,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR IS NOT NULL THROW 50000,@MSG,1;
DECLARE @INC BIGINT;EXEC INVENTARIO.SP_INCIDENTE_CREATE @EMP,@CO2,@DEP,@ASSET,@LOT,N'APERTURA_ACCIDENTAL',@NOW,11,.1,10.9,0,N'PESAJE',N'Smoke de pérdida',N'Aislamiento',NULL,1,@USR,@INC OUTPUT,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR IS NOT NULL THROW 50000,@MSG,1;
DECLARE @MAN BIGINT;EXEC INVENTARIO.SP_MANTENIMIENTO_CREATE @EMP,@ASSET,@INC,@PROV,N'CORRECTIVO',@NOW,N'Control de válvula',100,1,@USR,@MAN OUTPUT,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR IS NOT NULL THROW 50000,@MSG,1;
SELECT @RV=ROW_VERSION FROM INVENTARIO.MANTENIMIENTOS WHERE ID_MANTENIMIENTO=@MAN;EXEC INVENTARIO.SP_MANTENIMIENTO_COMPLETE @EMP,@MAN,@END,N'Operativo',N'Válvula usada',N'Válvula nueva',120,NULL,@NEXT,@RV,1,@USR,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR IS NOT NULL THROW 50000,@MSG,1;
SET @JSON=N'[{"AssetId":'+CONVERT(NVARCHAR(20),@ASSET)+N',"LotId":'+CONVERT(NVARCHAR(20),@LOT)+N',"Quantity":10.9,"ConditionCode":"OPERATIVO"}]';DECLARE @LOAN BIGINT;EXEC INVENTARIO.SP_PRESTAMO_CREATE @EMP,N'TERCERO',NULL,NULL,N'Taller externo',N'ENTREGA_PROPIA',@NOW,@NEXT,N'Smoke',NULL,NULL,@JSON,1,@USR,@LOAN OUTPUT,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR IS NOT NULL THROW 50000,@MSG,1;
DECLARE @LOANLINE BIGINT=(SELECT ID_PRESTAMO_DETALLE FROM INVENTARIO.PRESTAMOS_DETALLES WHERE ID_PRESTAMO=@LOAN);SELECT @RV=ROW_VERSION FROM INVENTARIO.PRESTAMOS WHERE ID_PRESTAMO=@LOAN;SET @JSON=N'[{"LoanLineId":'+CONVERT(NVARCHAR(20),@LOANLINE)+N',"Quantity":10.9,"ConditionCode":"OPERATIVO","Observation":"Sin diferencias"}]';EXEC INVENTARIO.SP_PRESTAMO_RETURN @EMP,@LOAN,@RETURN,N'Regreso correcto',@JSON,@RV,1,@USR,@ERR OUTPUT,@MSG OUTPUT,@ROWS OUTPUT;IF @ERR IS NOT NULL THROW 50000,@MSG,1;
IF NOT EXISTS(SELECT 1 FROM INVENTARIO.ACTIVOS_EVENTOS WHERE ID_ACTIVO=@ASSET AND ID_PRESTAMO=@LOAN) THROW 50000,'Falta historial.',1;
ROLLBACK TRANSACTION;SELECT N'SMOKE_FASE7_OK' AS RESULTADO;
